def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = set(classes)
    for subclass in classes:
        bases.update(subclass.__bases__)
    minbases = []
    for base in bases:
        if base in classes:
            continue
        newbases = minimalBases(base.__bases__)
        if len(newbases) < len(minbases) or len(newbases) == len(minbases) and base < minbases[-1]:
