def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """

    # Check that the object is a valid OCFL object
    if path.endswith('/'):
        path = path[:-1]

    if path != self.id and path != self.id[:self.id.rfind('/') + 1]:
        if self.nested:
            msg = f"Head object id ({self.id}) doesn't match path ({path})."
            print(f"WARNING: {msg}")
            return False
    if not self.id:
        msg = "Head object doesn't have an id attribute."
        print(f"WARNING: {msg}")
        return False

    if self.id != path:
        if self.graph:
            print(f"WARNING: Inconsistent id ({self.id}) for graph head ({self.graph}).")
        else:
            print(f"WARNING: Inconsistent id ({self.id}) for object ({self.path}).")

    if self.fold_structure:
        if not self.graph:
            print(f"WARNING: Head object doesn't have a Graph object.")
            return False

        graph = self.graph
        if graph.type != "http://www.w3.org/2002/07/owl#Ontology":
            print(f"WARNING: Graph type ({graph.type}) is not equal to 'http://www.w3.org/2002/07/owl#Ontology'")
            return False

        # Check that the graph is a valid OCFL graph
        if not graph.validate:
            print(f"WARNING: Graph.validate is False.")
            return False

        # Check that the graph is valid RDF
        if graph.parsetype not in ('xml', 'n3', 'turtle', 'rdfa'):
            print(f"WARNING: Graph parsetype ({graph.parsetype}) is not one of supported parsetypes ('xml', 'n3', 'turtle', 'rdfa')")
            return False

        rv = graph.validate_data()
        if not rv:
            print(f"WARNING: Graph data invalid.")
            return False

    # Check that the object is valid
    if not self.validate_structure:
        print(f"WARNING: Object is not valid.")
        return False

    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if path is None:
        path = "/"

    # Verify permissions
    if not self.has_permission("browse", "/"):
        return False

    # Verify inventory
    inventory = self.get_inventory(path)
    if inventory is None:
        return False

    # Verify digests
    if not self.verify_digests(inventory, path):
        return False

    # Verify directories
    for subpath in inventory["dirs"]:
        if not self.validate(subpath):
            return False

    # Verify files
    for subpath in inventory["files"]:
        if not self.validate_file(subpath):
            return False

    return True

