        if prior_version != current_version:
            raise ValueError("Edition '{ed_name}' has been updated from version "
                             "'{prior_version}' to '{current_version}'. Validation "
                             "as prior version failed.")

    prior_licenses = prior.licenses()
    current_licenses = self.licenses()
    for license_name in prior_licenses:
