    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    for required_attrib in self.REQUIRED_ATTRIBS:
        if required_attrib not in prior.attribs:
            raise AttributeError(f"Prior inventory does not have required attribute {required_attrib!r}.")

    self_attribs = set(self.attribs)
    prior_attribs = set(prior.attribs)

    if self_attribs != prior_attribs:
        raise AttributeError(f"Prior inventory has different attributes than current inventory: {', '.join(prior_attribs - self_attribs)}.")

    required_occurences = self.OCCURRENCES
    if required_occurences != prior.OCCURRENCES:
        raise ValueError(f"Prior inventory has {prior.OCCURRENCES} occurrences of the required attribute(s), but current inventory requires {required_occurences}.")

    current_occurences = {
        attrib: self.items(attrib=attrib).count()
        for attrib in self_attribs
    }
    prior_occurences = {
        attrib: prior.items(attrib=attrib).count()
        for attrib in prior_attribs
    }

    for attrib, current_count in current_occurences.items():
        if current_count != prior_occurences.get(attrib, 0):
            raise ValueError(f"Prior inventory has {prior_occurences.get(attrib, 0)} occurrence(s) of attribute {attrib!r}, but current inventory requires {current_count}.")

