    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    # Get the files for this version
    content_files = set()
    for file_metadata in version.files.values():
        content_files.add(file_metadata.path)

    # Get the logical paths for the files
    logical_paths = {}
    for file_metadata in version.files.values():
        if file_metadata.logical_path not in logical_paths:
            logical_paths[file_metadata.logical_path] = set()
        logical_paths[file_metadata.logical_path].add(file_metadata.path)

    # Get the logical paths for the inventory
    inventory_logical_paths = inventory.get_logical_paths()

    # Use the inventory logical paths to map the logical paths to their corresponding files
    logical_path_map = {}
    for logical_path in logical_paths:
        if logical_path in inventory_logical_paths:
            logical_path_map[logical_path] = logical_paths[logical_path] & content_files
        else:
            logical_path_map[logical_path] = logical_paths[logical_path]

