    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    for state in inventory:
        for substate in state.substates:
            for content in substate:
                if content.logical_path not in logical_path_map:
                    logical_path_map[content.logical_path] = {content.filename}
                else:
                    logical_path_map[content.logical_path].add(content.filename)

