        for version_index in range(version, 0, -1):
            for state in inventory[version_index].states:
                for substate in state.substates:
                    for content in substate.contents:
                        if content.logical_path in logical_path_map:
                            logical_path_map[content.logical_path].add(content.filename)

    return logical_path_map

