    for logical_path in logical_paths:
        if logical_path in inventory_logical_paths:
            logical_path_map[logical_path] = logical_paths[logical_path] & content_files
        else:
            logical_path_map[logical_path] = logical_paths[logical_path]

    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    logical_path_map = {}

    for state in inventory:
        for substate in state.substates:
            for content in substate:
                if content.logical_path not in logical_path_map:
                    logical_path_map[content.logical_path] = {content.filename}
                else:
                    logical_path_map[content.logical_path].add(content.filename)

    if version != inventory[0]:
        for version_index in range(version, 0, -1):
            for state in inventory[version_index].states:
                for substate in state.substates:
                    for content in substate.contents:
                        if content.logical_path in logical_path_map:
                            logical_path_map[content.logical_path].add(content.filename)

    return logical_path_map

