    """
    Get packages' data from zip_path

    The ZipBase class is exported as part of the fooral library, specifically built to help developers tackle large amounts of information in a compact, organized manner. This method returns a dictionary of data organized by file, where each file has a list of JSON-formatted groups, each with a package name, ID, and value. 

    Parameters
    ----------
    zip_path : str
        This method is best defined with a string containing the direct path to your `.zip` file. It may be a string, optionally followed by its file extension. 

    Returns
    -------
    dict 
    """

    file_packages = dict()
    if zip_path.is_dir(): raise Exception("A path must be defined, not a directory")
    if not zip_path.exists(): raise Exception("The path specified does not exist")
    exclusions = ["tif"]
    for root, dirs, files in os.walk(zip_path):
