        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    num = float(size[:-1])
    unit = size[-1]
    if unit == "K":
        return num * 1024
    elif unit == "M":
        return num * 1024 ** 2
    elif unit == "G":
        return num * 1024 ** 3
    elif unit == "T":
        return num * 1024 ** 4
    elif unit == "P":
        return num * 1024 ** 5
    elif unit == "E":
        return num * 1024 ** 6
    else:
        raise ValueError("Invalid file size unit")

    return int(num)

