def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    import re

    if platform == 'this':
        platform = '1' if os.name == 'posix' else '0'

    if platform == '1':
        pattern = r'(?:[^\s"\']|"(?:\\.|[^"])*"|'
        pattern += r"(?:\\.|'(?:\\.|[^'])*')"
        pattern += r')+'
        return re.findall(pattern, s)

    elif platform == '0':
        pattern = r'(["\'])((?:\\.|(?!\1)[^\\])*)\1'
        return re.findall(pattern, s)

    else:
        raise ValueError("Invalid platform value: " + platform)

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if re.search(r"\s", s):
            s = re.sub("\\\\(.)", r"\1", s)  # remove backslash escapes, ie. \N becomes N
            s = re.sub(r'"([^"]*?)"', r'\1', s)  # remove double quotes, ie. "any text in quotes" becomes any text in quotes
            s = re.sub(r"'([^']*?)'", r'\1', s)  # remove single quotes, ie. 'any text in single quotes' becomes any text in single quotes
            s = re.sub(r"/|;::?", r'', s)  # remove forward slashes, semicolons, and any instances of :::, ie. /some/long:/file/path becomes somelongfilepath
            s = re.sub(r"\s+", r' ', s)  # remove multiple spaces, ie. "  hello  world  " becomes "hello world"

            s = s.strip()  # remove any leading or trailing spaces
            s = re.sub(r'\b\s*>+$', r'', s)  # remove any trailing command redirection (ie. 'hello > world' becomes 'hello')
            s = re.sub(r'^>\s*\b', r'', s)  # remove any leading command redirection (ie. '> hello' becomes 'hello')

            return re.split(r"(\s+)", s)  # split on any number of spaces (IE. "hello  world  " becomes ['hello', 'world'])
