def scale(self, other=None, recompute=False):
    if other is None:
        if not self.scale_computed or recompute:
            self.scale = int(sum(self.values))
            self.scale_computed = True
        return self.scale
    else:
        if self.scale_computed and self.scale == 0:
            raise LenaValueError("Can't rescale histogram with scale equal to zero")
        new_values = [int(round(self.values[i] / self.scale * other)) for i, _ in enumerate(self.values)]
        return Histogram(values=new_values, scale=other)

