def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json

    if document[0] == "{":  # new format (JSON)
        return json.loads(document)
    else:  # old format (XRD)
        from urllib import parse

        parsed = parse.urlparse(document)
        if parsed.hostname != "protocol.fabrik.com":
            raise ValueError("Unsupported hostname")

        components = parsed.path.split("/")
        if len(components) < 3:
            raise ValueError("Invalid path format")

        if components[2] != "profile" or components[3] != "indirect":
            raise ValueError("Invalid path format")

        query_params = parse.parse_qs(parsed.query)
        href = query_params["href"]

        if not href:
            raise ValueError("No href parameter in URL")

        if len(href) > 1:
            raise ValueError("Multiple href parameters in URL")

        href = href[0]

        if not href.startswith("http"):
            raise ValueError("Href does not start with http")

        return {
            "href": href,
            "aliases": {alias for alias in query_params.get("alias", [])},
        }

