def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    with open(yaml_file, 'r') as f:
        data = yaml.safe_load(f)

    required_fields = {'name', 'description', 'simple_feature', 'properties', 'annotations'}

    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f'Missing mandatory field: {field}')

    if data['simple_feature'] not in ('item', 'value'):
        raise IRValidatorException('Invalid value for simple_feature: {data["simple_feature"]}')

    if not isinstance(data['properties'], dict):
        raise IRValidatorException('properties must be a dictionary')

    if not isinstance(data['annotations'], dict):
        raise IRValidatorException('annotations must be a dictionary')

    return data

