def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    # set default verbosity based on IR workspace's verbosity
    if verbose is None:
        verbose = 1 if ir_workspace.verbosity > 1 else 0
    # add default ansible args
    if ansible_args is None:
        ansible_args = ["--timeout", "30"]
    if extra_vars is None:
        extra_vars = {}
    # build command
    command = ["ansible-playbook", playbook_path, "-i", ir_workspace.basedir]
    if verbose:
        command.extend(["-" + "v" * verbose])
    for key, value in extra_vars.items():
        command.extend(["-e", f"{key}={value}"])
    command.extend(ansible_args)
    # execute command and get exit code
    exit_code = os.system(" ".join(command))
    # return exit code
    if exit_code == 0:
        return ir_plugin.run_history.success("Ansible Playbook '{0}' was executed successfully.".format(playbook_path), trace=playbook_path)
    else:
        return ir_plugin.run_history.failure("Ansible Playbook '{0}' failed with exit code '{1}'.".format(playbook_path, exit_code), trace=playbook_path)

